// The rest of the sheet tabs: a tab dragged to another place (mouse, finger),
// moved from its menu, a sheet hidden and shown again, copied, the colour of
// its tab; what is saved, undo, a read-only view and a formula being typed.
// And notes that travel with cells: copy, cut, paste and sort.
// Every workbook is generated by code.
import type { Locator, Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const MOUSE_ONLY = 'mouse input is covered by the desktop projects';
const TOUCH_ONLY = 'touch input is covered by the mobile projects';
/** Longer than a finger has to rest on a tab for its menu (LONG_PRESS_MS in the view, 550). */
const LONG_PRESS_WAIT = 700;

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const formula = (ref: string, text: string, value: number) => `<c r="${ref}"><f>${text}</f><v>${value}</v></c>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/** "Data": A1 = 1, A2 = Data!A1 + 1. "Calc": A1 = Data!A1. "Notes": empty. "Unseen": hidden. "Deep": very hidden. */
const book = once(() =>
  buildXlsx({
    sheets: [
      { name: 'Data', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 1)}</row><row r="2">${formula('A2', 'Data!A1+1', 2)}</row></sheetData>`) },
      { name: 'Calc', xml: worksheetXml(`<sheetData><row r="1">${formula('A1', 'Data!A1', 1)}</row></sheetData>`) },
      { name: 'Notes', xml: worksheetXml('<sheetData/>') },
      { name: 'Unseen', state: 'hidden', xml: worksheetXml(`<sheetData><row r="1">${num('A1', 2)}</row></sheetData>`) },
      { name: 'Deep', state: 'veryHidden', xml: worksheetXml('<sheetData/>') },
    ],
  }),
);

/** A sheet with a conditional format and a data validation, which a copy does not get. */
const rulesBook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Rules',
        xml: worksheetXml(
          `<sheetData><row r="1">${num('A1', 1)}</row></sheetData>` +
            '<conditionalFormatting sqref="A1:A9"><cfRule type="cellIs" priority="1" operator="greaterThan"><formula>0</formula></cfRule></conditionalFormatting>' +
            '<dataValidations count="1"><dataValidation type="whole" sqref="B1"><formula1>1</formula1><formula2>9</formula2></dataValidation></dataValidations>' +
            // Kept in the part and not in the model: two things a copy does not get.
            '<ignoredErrors><ignoredError sqref="A1" numberStoredAsText="1"/></ignoredErrors>' +
            '<extLst><ext uri="{78C0D931-6437-407d-A8EE-F0AAD7539E65}" xmlns:x14="http://schemas.microsoft.com/office/spreadsheetml/2009/9/main"><x14:conditionalFormattings>' +
            '<x14:conditionalFormatting xmlns:xm="http://schemas.microsoft.com/office/excel/2006/main"><x14:cfRule type="iconSet" priority="2" id="{00000000-000E-0000-0000-000001000000}">' +
            '<x14:iconSet iconSet="3Stars"><x14:cfvo type="percent"><xm:f>0</xm:f></x14:cfvo><x14:cfvo type="percent"><xm:f>33</xm:f></x14:cfvo><x14:cfvo type="percent"><xm:f>67</xm:f></x14:cfvo></x14:iconSet>' +
            '</x14:cfRule><xm:sqref>C1:C9</xm:sqref></x14:conditionalFormatting></x14:conditionalFormattings></ext></extLst>',
        ),
      },
    ],
  }),
);

/** More tabs than a phone is wide. */
const manyTabs = once(() =>
  buildXlsx({ sheets: Array.from({ length: 14 }, (_, i) => ({ name: `Sheet number ${i + 1}`, xml: worksheetXml('<sheetData/>') })) }),
);

interface MountOptions {
  locale?: string;
  readOnly?: boolean;
}

async function mount(page: Page, bytes: Uint8Array, options: MountOptions = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
      (window as any).__original = data;
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const tabs = (page: Page) => page.locator('.bym-tabs button.bym-tab');
const tab = (page: Page, name: string) => page.locator('.bym-tabs button.bym-tab', { hasText: name });
const selectedTab = (page: Page) => page.locator('.bym-tabs button[aria-selected="true"]');
const menu = (page: Page) => page.locator('.bym-view .bym-menu');
const palette = (page: Page) => page.locator('.bym-view .bym-popover');
const dropMark = (page: Page) => page.locator('.bym-tabs .bym-tab-drop');
const view = <T>(page: Page, run: string): Promise<T> => page.evaluate(`(() => { const view = window.__view; return ${run}; })()`) as Promise<T>;
const names = (page: Page): Promise<string[]> => view(page, 'view.workbook.sheets.map((sheet) => sheet.name)');
const states = (page: Page): Promise<string[]> => view(page, 'view.workbook.sheets.map((sheet) => sheet.name + ":" + sheet.state)');
const notices = (page: Page): Promise<{ message: string; kind: string }[]> => page.evaluate(() => (window as any).__notices.slice());

/** A pointer event of a finger on an element, at its middle moved by `dx`. */
async function touchEvent(target: Locator, type: string, dx = 0): Promise<void> {
  await target.evaluate(
    (element, [type, dx]) => {
      const rect = element.getBoundingClientRect();
      element.dispatchEvent(
        new PointerEvent(type as string, { pointerId: 41, pointerType: 'touch', isPrimary: true, clientX: rect.left + rect.width / 2 + (dx as number), clientY: rect.top + rect.height / 2, bubbles: true, cancelable: true }),
      );
    },
    [type, dx] as [string, number],
  );
}

/** Opens the menu of a tab the way the device does: a right click, or a finger that rests on the tab. */
async function openTabMenu(page: Page, name: string, hasTouch: boolean | undefined): Promise<void> {
  if (hasTouch) {
    await touchEvent(tab(page, name), 'pointerdown');
    await expect(menu(page)).toBeVisible();
    await touchEvent(tab(page, name), 'pointerup');
  } else {
    await tab(page, name).click({ button: 'right' });
  }
  await expect(menu(page)).toBeVisible();
}

async function press(item: Locator, hasTouch: boolean | undefined): Promise<void> {
  if (hasTouch) await item.tap();
  else await item.click();
}

/** Presses the item of the open menu whose label begins with `label`. */
async function chooseItem(page: Page, label: string, hasTouch: boolean | undefined): Promise<void> {
  await press(menu(page).locator('button', { hasText: new RegExp(`^${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`) }), hasTouch);
}

/** What the view saves, read again: the sheets in order with their state, tab colour and cells. */
function saved(page: Page): Promise<{ name: string; state: string; tab?: string; cells: Record<string, string>; notes: string[] }[]> {
  return page.evaluate(async () => {
    const api = (window as any).BymOffice;
    const bytes: Uint8Array = await (window as any).__file.save();
    const workbook = await (await api.open(bytes)).workbook();
    return workbook.sheets.map((sheet: any) => {
      const cells: Record<string, string> = {};
      sheet.rows.forEach((row: any, index: number) => {
        row.cells.forEach((data: any, col: number) => {
          if (data) cells[api.cellName(index, col)] = data.formula ? `=${data.formula.text}` : String(data.value);
        });
      });
      const notes = (sheet.comments || []).map((note: any) => `${api.cellName(note.row, note.col)}:${note.text}`).sort();
      const out: any = { name: sheet.name, state: sheet.state, cells, notes };
      if (sheet.tabColor) out.tab = sheet.tabColor.rgb;
      return out;
    });
  });
}

/** Whether the view saves the very bytes it was given. */
function savesOriginal(page: Page): Promise<boolean> {
  return page.evaluate(async () => {
    const bytes: Uint8Array = await (window as any).__file.save();
    const original: Uint8Array = (window as any).__original;
    if (bytes.length !== original.length) return false;
    for (let i = 0; i < bytes.length; i++) if (bytes[i] !== original[i]) return false;
    return true;
  });
}

async function undoAll(page: Page): Promise<number> {
  let steps = 0;
  while (steps < 40 && (await view(page, 'view.history.canUndo'))) {
    await view(page, 'view.undo()');
    steps++;
  }
  return steps;
}

test.describe('the menu of a tab', () => {
  test('lists what can be done to the sheet, and moves it left and right', async ({ page, hasTouch }) => {
    await mount(page, await book());
    await openTabMenu(page, 'Calc', hasTouch);
    await expect(menu(page).locator('button')).toHaveText(['Insert sheet', 'Rename', 'Delete', 'Duplicate', 'Move left', 'Move right', 'Hide', 'Unhide…', 'Protect sheet', 'Tab colour…']);
    await chooseItem(page, 'Move right', hasTouch);
    await expect(tabs(page)).toHaveText(['Data', 'Notes', 'Calc']);
    expect(await names(page)).toEqual(['Data', 'Notes', 'Calc', 'Unseen', 'Deep']);
    await expect(selectedTab(page)).toHaveText('Calc');
    // The formulas are the text they were.
    expect(await view(page, 'view.workbook.sheets[2].rows.get(0).cells[0].formula.text')).toBe('Data!A1');

    // The last tab cannot go further right; the first not further left.
    await openTabMenu(page, 'Calc', hasTouch);
    await expect(menu(page).locator('button', { hasText: 'Move right' })).toBeDisabled();
    await chooseItem(page, 'Move left', hasTouch);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    await openTabMenu(page, 'Data', hasTouch);
    await expect(menu(page).locator('button', { hasText: 'Move left' })).toBeDisabled();
    await page.keyboard.press('Escape');

    // Each move is one step.
    expect(await view(page, 'view.undo()')).toBe(true);
    await expect(tabs(page)).toHaveText(['Data', 'Notes', 'Calc']);
    expect(await view(page, 'view.undo()')).toBe(true);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await savesOriginal(page)).toBe(true);
  });

  test('from the keyboard: the menu moves the focused tab and the focus stays with it', async ({ page }) => {
    await mount(page, await book());
    await tab(page, 'Data').focus();
    await page.keyboard.press('Shift+F10');
    await expect(menu(page)).toBeVisible();
    await menu(page).locator('button', { hasText: 'Move right' }).focus();
    await page.keyboard.press('Enter');
    await expect(tabs(page)).toHaveText(['Calc', 'Data', 'Notes']);
    await expect(tab(page, 'Data')).toBeFocused();
    await expect(page.locator('.bym-view [aria-live]')).toHaveText('Sheet Data moved to place 2 of 3');
  });

  test('is as long as it is in a small view: every item can be reached', async ({ page, hasTouch }) => {
    await page.setViewportSize({ width: 360, height: 300 });
    await mount(page, await book());
    await openTabMenu(page, 'Calc', hasTouch);
    const last = menu(page).locator('button', { hasText: 'Tab colour' });
    await last.scrollIntoViewIfNeeded();
    await expect(last).toBeVisible();
    const box = await menu(page).boundingBox();
    const root = await page.locator('.bym-view').boundingBox();
    expect(box!.y).toBeGreaterThanOrEqual(root!.y - 1);
    expect(box!.y + box!.height).toBeLessThanOrEqual(root!.y + root!.height + 1);
    await page.keyboard.press('End');
    await expect(last).toBeFocused();
  });
});

test.describe('dragging a tab', () => {
  test('with the mouse: a line shows where it goes, and letting go moves the sheet as one step', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    const from = (await tab(page, 'Data').boundingBox())!;
    const to = (await tab(page, 'Notes').boundingBox())!;
    await page.mouse.move(from.x + from.width / 2, from.y + from.height / 2);
    await page.mouse.down();
    // A few pixels are a click, not a drag.
    await page.mouse.move(from.x + from.width / 2 + 3, from.y + from.height / 2);
    await expect(dropMark(page)).toHaveCount(0);
    await page.mouse.move(to.x + to.width - 4, to.y + to.height / 2, { steps: 4 });
    await expect(dropMark(page)).toBeVisible();
    const mark = (await dropMark(page).boundingBox())!;
    expect(Math.abs(mark.x + mark.width / 2 - (to.x + to.width))).toBeLessThanOrEqual(3);
    await page.mouse.up();
    await expect(dropMark(page)).toHaveCount(0);
    await expect(tabs(page)).toHaveText(['Calc', 'Notes', 'Data']);
    // The hidden sheets stay behind the tabs they were behind.
    expect(await names(page)).toEqual(['Calc', 'Notes', 'Data', 'Unseen', 'Deep']);
    // The sheet that was shown is still the one shown.
    await expect(selectedTab(page)).toHaveText('Data');

    // Dropped on the left half of the first tab: first.
    const first = (await tab(page, 'Calc').boundingBox())!;
    const data = (await tab(page, 'Data').boundingBox())!;
    await page.mouse.move(data.x + data.width / 2, data.y + data.height / 2);
    await page.mouse.down();
    await page.mouse.move(first.x + 3, first.y + first.height / 2, { steps: 4 });
    await page.mouse.up();
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);

    // Dropped beside itself: nothing happens, and no step is made.
    const steps = await view<boolean>(page, 'view.history.canUndo');
    expect(steps).toBe(true);
    const calc = (await tab(page, 'Calc').boundingBox())!;
    await page.mouse.move(calc.x + calc.width / 2, calc.y + calc.height / 2);
    await page.mouse.down();
    await page.mouse.move(calc.x + calc.width / 2 + 12, calc.y + calc.height / 2, { steps: 2 });
    await page.mouse.up();
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await undoAll(page)).toBe(2);
    expect(await savesOriginal(page)).toBe(true);

    // A click is still a click.
    await tab(page, 'Notes').click();
    await expect(selectedTab(page)).toHaveText('Notes');
  });

  test('with a finger: a tab that was held and is then moved is dragged, and the menu gives way', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await book());
    const target = tab(page, 'Data');
    const width = (await target.boundingBox())!.width;
    const reach = width / 2 + (await tab(page, 'Calc').boundingBox())!.width + 4;
    await touchEvent(target, 'pointerdown');
    await page.waitForTimeout(LONG_PRESS_WAIT);
    // Held: the menu is there, as before.
    await expect(menu(page)).toBeVisible();
    await touchEvent(target, 'pointermove', 3);
    await expect(menu(page)).toBeVisible();
    await touchEvent(target, 'pointermove', reach);
    await expect(menu(page)).toHaveCount(0);
    await expect(dropMark(page)).toBeVisible();
    await page.locator('.bym-tabs').evaluate(
      (element, x) => element.dispatchEvent(new PointerEvent('pointerup', { pointerId: 41, pointerType: 'touch', isPrimary: true, clientX: x as number, clientY: element.getBoundingClientRect().top + 5, bubbles: true, cancelable: true })),
      (await target.boundingBox())!.x + width / 2 + reach,
    );
    await expect(dropMark(page)).toHaveCount(0);
    await expect(tabs(page)).toHaveText(['Calc', 'Data', 'Notes']);
    // The click some browsers send after the finger is lifted chooses no tab.
    await tab(page, 'Notes').evaluate((element) => element.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, detail: 1 })));
    await expect(selectedTab(page)).toHaveText('Data');
    expect(await view(page, 'view.undo()')).toBe(true);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);

    // A finger that moves before it was held scrolls the strip, and drags nothing.
    await touchEvent(target, 'pointerdown');
    await touchEvent(target, 'pointermove', reach);
    await expect(dropMark(page)).toHaveCount(0);
    await touchEvent(target, 'pointercancel', reach);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
  });

  test('at the end of the strip the tabs scroll under the dragged one', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await page.setViewportSize({ width: 520, height: 720 });
    await mount(page, await manyTabs());
    const strip = (await page.locator('.bym-tabs').boundingBox())!;
    const first = (await tab(page, 'Sheet number 1').first().boundingBox())!;
    await page.mouse.move(first.x + first.width / 2, first.y + first.height / 2);
    await page.mouse.down();
    await page.mouse.move(strip.x + strip.width - 6, first.y + first.height / 2, { steps: 5 });
    await expect(dropMark(page)).toBeVisible();
    // The strip scrolls to its end while the pointer rests at its edge.
    await expect.poll(() => page.locator('.bym-tabs').evaluate((element) => `${element.scrollLeft + element.clientWidth >= element.scrollWidth - 2} ${element.scrollLeft} ${element.clientWidth} ${element.scrollWidth}`), { timeout: 15000 }).toMatch(/^true/);
    await page.mouse.up();
    expect((await names(page))[13]).toBe('Sheet number 1');
    expect((await names(page))[0]).toBe('Sheet number 2');
  });
});

test.describe('hiding and showing a sheet', () => {
  test('the menu hides a sheet and lists the hidden ones to show again', async ({ page, hasTouch }) => {
    await mount(page, await book());
    await openTabMenu(page, 'Data', hasTouch);
    await chooseItem(page, 'Hide', hasTouch);
    await expect(tabs(page)).toHaveText(['Calc', 'Notes']);
    // The sheet that was shown is hidden: the next one with a tab is shown.
    await expect(selectedTab(page)).toHaveText('Calc');
    expect(await states(page)).toEqual(['Data:hidden', 'Calc:visible', 'Notes:visible', 'Unseen:hidden', 'Deep:veryHidden']);

    await openTabMenu(page, 'Notes', hasTouch);
    await chooseItem(page, 'Unhide', hasTouch);
    // The hidden sheets, not the very hidden one.
    await expect(menu(page)).toHaveAttribute('aria-label', 'Hidden sheets');
    await expect(menu(page).locator('button')).toHaveText(['Data', 'Unseen']);
    await chooseItem(page, 'Unseen', hasTouch);
    await expect(menu(page)).toHaveCount(0);
    await expect(tabs(page)).toHaveText(['Calc', 'Notes', 'Unseen']);
    await expect(selectedTab(page)).toHaveText('Unseen');

    const file = await saved(page);
    expect(file.map((sheet) => `${sheet.name}:${sheet.state}`)).toEqual(['Data:hidden', 'Calc:visible', 'Notes:visible', 'Unseen:visible', 'Deep:veryHidden']);

    expect(await undoAll(page)).toBe(2);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    await expect(selectedTab(page)).toHaveText('Data');
    expect(await savesOriginal(page)).toBe(true);
  });

  test('the last sheet with a tab cannot be hidden, and says why; a very hidden sheet is shown through the view alone', async ({ page, hasTouch }) => {
    await mount(page, await book());
    expect(await view(page, 'view.setSheetState(1, "hidden")')).toBe(true);
    expect(await view(page, 'view.setSheetState(2, "hidden")')).toBe(true);
    await openTabMenu(page, 'Data', hasTouch);
    const item = menu(page).locator('button', { hasText: /^Hide/ });
    await expect(item).toHaveAttribute('aria-disabled', 'true');
    // The item says that it is not available, which is why the test has to insist.
    await item.dispatchEvent('pointerdown');
    await item.dispatchEvent('click');
    await expect(menu(page)).toBeVisible();
    expect((await notices(page)).pop()).toEqual({ message: 'The last visible sheet cannot be hidden', kind: 'error' });
    await page.keyboard.press('Escape');
    expect(await view(page, '(() => { try { view.setSheetState(0, "hidden"); return "done"; } catch (error) { return error.message; } })()')).toBe('Cannot hide the last visible sheet');

    expect(await view(page, 'view.hiddenSheets')).toEqual([1, 2, 3]);
    expect(await view(page, 'view.setSheetState(4, "visible")')).toBe(true);
    await expect(tabs(page)).toHaveText(['Data', 'Deep']);
    await expect(selectedTab(page)).toHaveText('Deep');
  });
});

test.describe('copying a sheet', () => {
  test('the menu puts a copy behind the sheet and shows it; its formulas name the copy', async ({ page, hasTouch }) => {
    await mount(page, await book());
    await openTabMenu(page, 'Data', hasTouch);
    await chooseItem(page, 'Duplicate', hasTouch);
    await expect(tabs(page)).toHaveText(['Data', 'Data (2)', 'Calc', 'Notes']);
    await expect(selectedTab(page)).toHaveText('Data (2)');
    const file = await saved(page);
    expect(file.map((sheet) => sheet.name)).toEqual(['Data', 'Data (2)', 'Calc', 'Notes', 'Unseen', 'Deep']);
    expect(file[1].cells).toEqual({ A1: '1', A2: "='Data (2)'!A1+1" });
    expect(file[0].cells).toEqual({ A1: '1', A2: '=Data!A1+1' });
    expect(file[2].cells).toEqual({ A1: '=Data!A1' });
    expect(await view(page, 'view.copySheet(0, { name: "Third", at: 0 })')).toBe(0);
    await expect(tabs(page)).toHaveText(['Third', 'Data', 'Data (2)', 'Calc', 'Notes']);
    expect(await undoAll(page)).toBe(2);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await savesOriginal(page)).toBe(true);
  });

  test('what a copy does not get is said, with its number', async ({ page }) => {
    await mount(page, await rulesBook());
    expect(await view(page, 'view.copySheet(0)')).toBe(1);
    // The rules of the sheet go with the copy; what only the part holds does not.
    await expect.poll(async () => (await notices(page)).map((notice) => notice.message)).toContain('Sheet Rules was copied without: 1 conditional format setting of a newer Excel, 1 list of ignored errors');
    const file = await saved(page);
    expect(file.map((sheet) => sheet.name)).toEqual(['Rules', 'Rules (2)']);
    expect(
      await page.evaluate(async () => {
        const api = (window as any).BymOffice;
        const book = await (await api.open((await (window as any).__file.save()) as Uint8Array)).workbook();
        const copy = book.sheets[1];
        return [copy.conditionalFormats.map((format: any) => format.rules.map((rule: any) => rule.type).join(',')), copy.dataValidations.map((rule: any) => rule.type)];
      }),
    ).toEqual([['cellIs'], ['whole']]);
  });
});

test.describe('the colour of a tab', () => {
  test('the menu opens the palette; a colour is shown on the tab, saved, and taken away again', async ({ page, hasTouch }) => {
    await mount(page, await book());
    await openTabMenu(page, 'Calc', hasTouch);
    await chooseItem(page, 'Tab colour', hasTouch);
    await expect(palette(page)).toBeVisible();
    await press(palette(page).locator('[data-color="#FF0000"]'), hasTouch);
    await expect(palette(page)).toHaveCount(0);
    await expect(tab(page, 'Calc')).toHaveCSS('box-shadow', /rgb\(255, 0, 0\)/);
    expect((await saved(page))[1].tab).toBe('FFFF0000');
    expect(await view(page, 'view.workbook.sheets[1].modified')).toBeFalsy();

    await openTabMenu(page, 'Calc', hasTouch);
    await chooseItem(page, 'Tab colour', hasTouch);
    await press(palette(page).locator('button', { hasText: 'No colour' }), hasTouch);
    await expect(tab(page, 'Calc')).toHaveCSS('box-shadow', 'none');
    expect((await saved(page))[1].tab).toBeUndefined();

    expect(await view(page, 'view.setTabColor(0, "#00ff00")')).toBe(true);
    expect(await view(page, '(() => { try { view.setTabColor(0, "green"); return "done"; } catch (error) { return error.message; } })()')).toBe('A tab colour is written #RRGGBB');
    expect(await undoAll(page)).toBe(3);
    expect(await savesOriginal(page)).toBe(true);
  });

  test('Escape closes the palette and goes back to the tab', async ({ page }) => {
    await mount(page, await book());
    await tab(page, 'Notes').focus();
    await page.keyboard.press('Shift+F10');
    await menu(page).locator('button', { hasText: 'Tab colour' }).focus();
    await page.keyboard.press('Enter');
    await expect(palette(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(palette(page)).toHaveCount(0);
    await expect(tab(page, 'Notes')).toBeFocused();
  });
});

