test.describe('notes travel with their cells', () => {
  test('a copy inside the view pastes its notes, a cut takes them away, a sort moves them with their rows', async ({ page }) => {
    await mount(page, await book());
    // Data: A1 = 1 with a note, A2 = a formula; A3 = 0 so that a sort moves the rows.
    await page.evaluate(() => {
      const view = (window as any).__view;
      (window as any).__at = (row: number, col: number) => view.select({ top: row, left: col, bottom: row, right: col });
      view.setComment(0, 0, 'first');
      view.setCellInput(2, 0, '0');
      (window as any).__at(0, 0);
      const copied = view.copy();
      (window as any).__at(0, 3);
      view.paste(copied.text, copied.html);
      // Text that only looks the same brings no note.
      (window as any).__at(0, 5);
      view.paste(copied.text, '<table><tr><td>1</td></tr></table>');
    });
    expect((await saved(page))[0].notes).toEqual(['A1:first', 'D1:first']);
    expect((await saved(page))[0].cells.F1).toBe('1');

    await page.evaluate(() => {
      const view = (window as any).__view;
      (window as any).__at(0, 3);
      const cut = view.cut();
      (window as any).__at(4, 3);
      view.paste(cut.text, cut.html);
    });
    expect((await saved(page))[0].notes).toEqual(['A1:first', 'D5:first']);
    // The cut is one step: the cell and its note come back together.
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await saved(page))[0].notes).toEqual(['A1:first', 'D1:first']);

    // Sorted by column A (1, 2, 0): the 0 comes first, and the note of the 1 goes down with its row.
    await page.evaluate(() => {
      const view = (window as any).__view;
      view.select({ top: 0, left: 0, bottom: 2, right: 0 }, { row: 0, col: 0 });
      view.sort(false);
    });
    const file = await saved(page);
    expect(file[0].cells.A1).toBe('0');
    expect(file[0].cells.A2).toBe('1');
    expect(file[0].notes).toEqual(['A2:first', 'D1:first']);
    await view(page, 'view.undo()');
    expect((await saved(page))[0].notes).toEqual(['A1:first', 'D1:first']);
  });
});

test.describe('review: a drag that is given up', () => {
  test('a press on a tab that is let go outside the strip leaves nothing behind: hovering drags no tab and a click moves no sheet', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    const data = (await tab(page, 'Data').boundingBox())!;
    const notes = (await tab(page, 'Notes').boundingBox())!;
    const strip = (await page.locator('.bym-tabs').boundingBox())!;
    const y = data.y + data.height / 2;
    await page.mouse.move(data.x + data.width / 2, y);
    await page.mouse.down();
    // Up and away over the cells, less far sideways than a drag takes, and let go there.
    await page.mouse.move(data.x + data.width / 2 + 2, y - 150, { steps: 3 });
    await page.mouse.up();
    // Back over the strip with no button down.
    await page.mouse.move(data.x + data.width / 2, y, { steps: 2 });
    await page.mouse.move(notes.x + notes.width - 4, y, { steps: 5 });
    await expect(dropMark(page)).toHaveCount(0);
    expect(await page.locator('.bym-tabs [data-dragging]').count()).toBe(0);
    // A click on the empty end of the strip.
    await page.mouse.click(strip.x + strip.width - 8, y);
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await names(page)).toEqual(['Data', 'Calc', 'Notes', 'Unseen', 'Deep']);
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    expect(await page.locator('.bym-tabs').evaluate((element) => (element as HTMLElement).style.cursor)).toBe('');

    // A drag that was begun and whose button is let go outside the window: the next move without a button ends it.
    await page.mouse.move(data.x + data.width / 2, y);
    await page.mouse.down();
    await page.mouse.move(notes.x + notes.width - 4, y, { steps: 4 });
    await expect(dropMark(page)).toBeVisible();
    await page.locator('.bym-tabs').evaluate((element, [x, y]) => element.dispatchEvent(new PointerEvent('pointermove', { pointerId: (window as any).__view.tabDrag.pointerId, pointerType: 'mouse', isPrimary: true, buttons: 0, clientX: x, clientY: y, bubbles: true, cancelable: true })), [notes.x + 10, y]);
    await expect(dropMark(page)).toHaveCount(0);
    expect(await page.locator('.bym-tabs [data-dragging]').count()).toBe(0);
    expect(await page.locator('.bym-tabs').evaluate((element) => (element as HTMLElement).style.cursor)).toBe('');
    await page.mouse.up();
    await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    expect(await savesOriginal(page)).toBe(true);
  });

  test('Escape gives a drag up, and so does whatever changes the workbook under it', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await book());
    await view(page, 'view.setCellInput(5, 5, "x")');
    const drag = async () => {
      const data = (await tab(page, 'Data').boundingBox())!;
      const notes = (await tab(page, 'Notes').boundingBox())!;
      await page.mouse.move(data.x + data.width / 2, data.y + data.height / 2);
      await page.mouse.down();
      await page.mouse.move(notes.x + notes.width - 4, notes.y + notes.height / 2, { steps: 4 });
      await expect(dropMark(page)).toBeVisible();
    };
    const given = async () => {
      await expect(dropMark(page)).toHaveCount(0);
      expect(await page.locator('.bym-tabs [data-dragging]').count()).toBe(0);
      expect(await page.locator('.bym-tabs').evaluate((element) => (element as HTMLElement).style.cursor)).toBe('');
      await page.mouse.up();
      await expect(tabs(page)).toHaveText(['Data', 'Calc', 'Notes']);
    };
    await drag();
    await page.keyboard.press('Escape');
    await given();
    // The sheet that was shown is still shown, and the cell is as it was typed.
    await expect(selectedTab(page)).toHaveText('Data');
    expect(await view(page, 'view.history.canUndo')).toBe(true);

    await drag();
    await view(page, 'view.setReadOnly(true)');
    await given();
    await view(page, 'view.setReadOnly(false)');

    await drag();
    expect(await view(page, 'view.undo()')).toBe(true);
    await given();
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    expect(await names(page)).toEqual(['Data', 'Calc', 'Notes', 'Unseen', 'Deep']);
  });
});

test.describe('review: what is being typed is applied before the sheets change', () => {
  test('a note in its field is in the copy of its sheet; a note that cannot be applied stops the operation', async ({ page }) => {
    await mount(page, await book());
    expect(await view(page, 'view.editComment(0, 0)')).toBe(true);
    await page.keyboard.type('kopya');
    expect(await view(page, 'view.isEditingComment')).toBe(true);
    expect(await view(page, 'view.copySheet(0)')).toBe(1);
    expect(await view(page, 'view.isEditingComment')).toBe(false);
    const file = await saved(page);
    expect(file[0].notes).toEqual(['A1:kopya']);
    expect(file[1].notes).toEqual(['A1:kopya']);

    // A text no note can hold: nothing is done to the sheets, the field stays open, and it is said why.
    for (const run of ['view.deleteSheet(1)', 'view.insertSheet()', 'view.moveSheet(0, 2)', 'view.setSheetState(2, "hidden")', 'view.setTabColor(0, "#ff0000")', 'view.copySheet(0)', 'view.renameSheet(0, "Other")']) {
      expect(await view(page, 'view.editComment(0, 0)')).toBe(true);
      await page.evaluate(() => {
        const field = document.activeElement as HTMLTextAreaElement;
        field.value = 'x'.repeat(40000);
        (window as any).__notices.length = 0;
      });
      const answer = await view<number | boolean>(page, run);
      expect(answer === false || answer === -1, run).toBe(true);
      expect(await view(page, 'view.isEditingComment'), run).toBe(true);
      expect(await names(page), run).toEqual(['Data', 'Data (2)', 'Calc', 'Notes', 'Unseen', 'Deep']);
      expect(await states(page), run).toEqual(['Data:visible', 'Data (2):visible', 'Calc:visible', 'Notes:visible', 'Unseen:hidden', 'Deep:veryHidden']);
      expect((await notices(page)).map((notice) => notice.message), run).toEqual(['A note cannot be longer than 32767 characters']);
      await page.keyboard.press('Escape');
      expect(await view(page, 'view.isEditingComment'), run).toBe(false);
    }
    expect(await view(page, 'view.workbook.sheets[0].tabColor')).toBeUndefined();
  });
});
